    blogCyprusFaq4Q: "How much does an airport transfer cost in Cyprus?",
    blogCyprusFaq4A: "Private transfers from Larnaca start from €35-45 to Larnaca city, €60-75 to Limassol, and €90-110 to Paphos.",
    blogCyprusFaq5Q: "Is there public transport from Cyprus airports?",
    blogCyprusFaq5A: "Yes, but it's limited. Larnaca has some bus services but they don't cover all destinations. Private transfer is more reliable.",
    blogCyprusFaq6Q: "Can I book a transfer from Larnaca to North Cyprus?",
    blogCyprusFaq6A: "Yes, we offer transfers to North Cyprus including Kyrenia and Famagusta. Border crossing takes about 15-20 minutes.",
    
    // Bursa Day Tour Guide - Detailed
    blogBursaSeoTitle: "Istanbul to Bursa Day Tour Guide 2025 | What to See & How to Get There",
    blogBursaSeoDesc: "Complete guide to visiting Bursa from Istanbul. Best attractions, transportation options, tour itineraries, and tips for the perfect day trip.",
    blogBursaH1: "Istanbul to Bursa Day Tour Guide 2025",
