    blogBursaSection1Title: "Why Visit Bursa from Istanbul?",
    blogBursaSection1P1: "Bursa, known as 'Green Bursa' (Yeşil Bursa), is one of Turkey's most historically significant cities. As the first capital of the Ottoman Empire (1335-1363), Bursa is home to stunning Ottoman architecture, UNESCO-listed Cumalıkızık village, and Turkey's most popular ski resort, Uludağ.",
    blogBursaSection1P2: "Unlike the crowded streets of Istanbul, Bursa offers a more relaxed pace with equally impressive historical sites. Plus, it's the birthplace of the legendary İskender kebab!",
