    blogBursaCumalikizikSubtitle: "UNESCO World Heritage Site - 700-year-old Ottoman village",
    blogBursaGrandMosqueTitle: "Grand Mosque (Ulu Cami)",
    blogBursaGrandMosqueDesc: "The iconic 20-domed mosque built in 1399. One of the finest examples of early Ottoman architecture with beautiful calligraphy.",
    blogBursaGreenMosqueTitle: "Green Mosque & Tomb (Yeşil Cami)",
    blogBursaGreenMosqueDesc: "Named for its stunning green-blue Iznik tiles. This 15th-century mosque complex showcases the peak of Ottoman artistry.",
    blogBursaCumalikizikCardTitle: "Cumalıkızık Village",
    blogBursaCumalikizikCardDesc: "This 700-year-old UNESCO village has preserved its original Ottoman character with colorful wooden houses and cobblestone streets.",
    blogBursaUludagTitle: "Uludağ Mountain & Cable Car",
    blogBursaUludagDesc: "Take the world's longest cable car to Uludağ National Park. In winter it's Turkey's premier ski resort; in summer enjoy hiking.",
    blogBursaKozaHanTitle: "Koza Han (Silk Bazaar)",
    blogBursaKozaHanDesc: "Historic covered marketplace from 1491, center of Bursa's famous silk trade. Enjoy Turkish coffee in the courtyard cafe.",
    blogBursaThermalTitle: "Çekirge Thermal Baths",
    blogBursaThermalDesc: "Bursa has been famous for its thermal springs since Roman times. Historic hamams with naturally hot mineral waters.",
    blogBursaCableCarTitle: "Uludağ Cable Car (Teleferik)",
    blogBursaCableCarSubtitle: "World's longest cable car ride with spectacular mountain views",
