    blogBursaFaq2Q: "Is a day trip from Istanbul to Bursa worth it?",
    blogBursaFaq2A: "Absolutely! Bursa offers Ottoman architecture, Uludağ mountain, UNESCO-listed Cumalıkızık, famous İskender kebab, and thermal springs.",
