    blogBursaFaq4A: "Our tours include hotel pickup/drop-off in Istanbul, luxury Mercedes vehicle, professional driver, all tolls and fees, and flexible itinerary.",
    blogBursaFaq5Q: "When is the best time to visit Bursa?",
    blogBursaFaq5A: "Spring (April-May) and autumn (September-October) offer pleasant weather. Winter is perfect for skiing. Summer can be hot.",
