    blogIstanbulPrivateFeature7: "No hidden fees or surge pricing",
    blogIstanbulPrivatePricing: "Private Transfer Pricing",
    blogIstanbulPrivatePricingP1: "Private transfer prices from Istanbul Airport are fixed and transparent:",
    blogIstanbulMetroRoute: "Metro Route",
    blogIstanbulMetroRouteP1: "The M11 line runs from Istanbul Airport to Gayrettepe station, where you can transfer to:",
