    blogIstanbulMetroMarmaray: "Marmaray: To Asian side via undersea tunnel",
    blogIstanbulMetroTimings: "Metro Timings",
    blogIstanbulMetroTimingsP1: "The metro operates from approximately 6:00 AM to midnight. Trains run every 8-10 minutes during peak hours and every 15-20 minutes during off-peak times.",
    blogIstanbulHavalistRoutes: "Main Havaist Routes",
    blogIstanbulHavalistRoutesP1: "Havaist is the official airport bus service connecting Istanbul Airport to various parts of the city. It's a good middle-ground option between metro and private transfer.",
