    blogIstanbulBestForMajor: "Budget, Major destinations",
    blogIstanbulFaq1Q: "What is the fastest way to get from Istanbul Airport to city center?",
    blogIstanbulFaq1A: "The fastest way is by private transfer, taking approximately 35-45 minutes to Taksim or Sultanahmet depending on traffic. The metro takes about 50-60 minutes but requires transfers.",
    blogIstanbulFaq2Q: "How much does regular transportation cost from Istanbul Airport to Taksim?",
    blogIstanbulFaq2A: "Regular transportation from Istanbul Airport to Taksim typically costs between 600-800 TL ($20-25 USD) depending on traffic and time of day. Prices can be higher at night or during peak hours.",
    blogIstanbulFaq3Q: "Is there a metro from Istanbul Airport?",
    blogIstanbulFaq3A: "Yes, the M11 metro line connects Istanbul Airport to Gayrettepe station, where you can transfer to the M2 line to reach Taksim. The journey takes approximately 50-60 minutes.",
    blogIstanbulFaq4Q: "What is the best option for families with children?",
    blogIstanbulFaq4A: "Private transfer is the best option for families. It offers door-to-door service, child seats upon request, help with luggage, and no waiting or transfers required.",
    blogIstanbulFaq5Q: "Are private transfers available 24/7?",
    blogIstanbulFaq5A: "Yes, Meet Transfer offers 24/7 private transfer services with flight tracking. Your driver will monitor your flight and adjust pickup time automatically for delays.",
    blogIstanbulFaq6Q: "How do I book a private transfer from Istanbul Airport?",
    blogIstanbulFaq6A: "You can book through our website's reservation form or contact us via WhatsApp for instant booking. We'll send you a price quote within minutes.",
    
    // Cappadocia Blog Translations
    blogCappadociaFaq1Q: "Which airport is closest to Cappadocia?",
    blogCappadociaFaq1A: "Nevsehir-Kapadocia Airport (NAV) is only 40 km from Göreme. Kayseri Airport (ASR) is 80 km away but offers more flight options.",
    blogCappadociaFaq2Q: "How long is the transfer from airport to hotel?",
    blogCappadociaFaq2A: "From Nevsehir Airport to Göreme it takes approximately 35-45 minutes, from Kayseri Airport it takes 60-75 minutes.",
    blogCappadociaFaq3Q: "Is there transfer service for balloon tours?",
    blogCappadociaFaq3A: "Yes, we offer early morning transfer service for balloon tours between 04:00-05:00 AM. Hotel pickup is included.",
    blogCappadociaFaq4Q: "What is included in transfer prices?",
    blogCappadociaFaq4A: "All taxes, flight tracking, free waiting time (60 min), door-to-door service, child seat (on request), and 24/7 support are included.",
    blogCappadociaFaq5Q: "Which areas do you transfer to in Cappadocia?",
    blogCappadociaFaq5A: "We offer transfers to Göreme, Ürgüp, Uchisar, Avanos, Nevşehir city center, Ortahisar, Mustafapaşa and all boutique hotels.",
    blogCappadociaFaq6Q: "Is late night transfer available?",
    blogCappadociaFaq6A: "Yes, we offer 24/7 transfer service. There is no extra charge for night flights.",
    blogCappadociaSeoTitle: "Cappadocia Airport Transfer Guide 2025 | Prices & Balloon Tours",
