    blogBursaSection1Title: "Warum Bursa von Istanbul besuchen?",
    blogBursaSection1P1: "Bursa, bekannt als 'Grünes Bursa' (Yeşil Bursa), ist eine der historisch bedeutendsten Städte der Türkei. Als erste Hauptstadt des Osmanischen Reiches (1335-1363) beherbergt Bursa beeindruckende osmanische Architektur, das UNESCO-gelistete Dorf Cumalıkızık und den beliebtesten Skiort der Türkei, den Uludağ.",
    blogBursaSection1P2: "Im Gegensatz zu den überfüllten Straßen Istanbuls bietet Bursa ein entspannteres Tempo mit ebenso beeindruckenden historischen Stätten. Außerdem ist es die Geburtsstätte des legendären İskender Kebabs!",
