    blogBursaCtaButton: "Bursa Touren ansehen",
    blogBursaFaq1Q: "Wie weit ist Bursa von Istanbul entfernt?",
    blogBursaFaq1A: "Bursa liegt etwa 150 km von Istanbul entfernt. Mit dem Auto dauert die Fahrt etwa 2-2,5 Stunden über die Osmangazi-Brücke, oder 3-3,5 Stunden mit der Fähre + Bus-Kombination.",
    blogBursaFaq2Q: "Kann ich Bursa an einem Tag von Istanbul aus besuchen?",
    blogBursaFaq2A: "Ja! Ein Tagesausflug ist der beliebteste Weg, Bursa zu erleben. Mit einem privaten Transfer können Sie um 8 Uhr abreisen und gegen 20-21 Uhr zurückkehren.",
    blogBursaFaq3Q: "Was ist die beste Reisezeit für Bursa?",
    blogBursaFaq3A: "Frühling (April-Mai) und Herbst (September-Oktober) bieten ideales Wetter. Der Winter ist perfekt für Skifahren am Uludağ, während der Sommer am wärmsten ist.",
    blogBursaFaq4Q: "Ist ein privater Transfer für einen Tagesausflug nach Bursa es wert?",
    blogBursaFaq4A: "Auf jeden Fall! Öffentliche Verkehrsmittel nach Bursa sind begrenzt und zeitaufwändig. Ein privater Transfer ermöglicht es Ihnen, an einem einzigen Tag alle Hauptattraktionen zu besuchen.",
    blogBursaFaq5Q: "Was sollte ich in Bursa essen?",
    blogBursaFaq5A: "İskender Kebab ist ein Muss! Diese in Bursa erfundene Spezialität besteht aus Döner-Fleisch auf Brot mit Tomatensauce und Butter. Probieren Sie auch Kestane Şekeri (kandierte Maronen).",
    blogBursaFaq6Q: "Was ist Cumalıkızık und warum ist es besonders?",
    blogBursaFaq6A: "Cumalıkızık ist ein 700 Jahre altes osmanisches Dorf und UNESCO-Welterbe. Es bietet traditionelle Architektur, Kopfsteinpflasterstraßen und authentische türkische Frühstückserlebnisse.",
    blogBursaCumalikizikAlt: "Cumalıkızık UNESCO-Dorf in Bursa",
    blogBursaUludagAlt: "Uludağ-Seilbahn im Winter",
    
