    // ============================================
    blogIstCity1Title: "Einführung: Ankommen in Istanbul",
    blogIstCity1P1: "Istanbul ist eine der meistbesuchten Städte der Welt und empfängt jährlich über 15 Millionen Touristen. Die Stadt hat zwei Flughäfen: Istanbul Airport (IST) auf der europäischen Seite und Sabiha Gökçen (SAW) auf der asiatischen Seite.",
    blogIstCity1P2: "In diesem umfassenden Guide vergleichen wir alle Transportoptionen und helfen Ihnen, die beste für Ihre Bedürfnisse zu wählen.",
    blogIstCityCompareTitle: "Transportoptionen im Vergleich",
    blogIstCityCompareP1: "Von beiden Flughäfen erreichen Sie das Stadtzentrum mit privatem Transfer, Taxi, Metro oder Bus. Jede Option hat ihre Vor- und Nachteile.",
    blogIstCityPrivateTitle: "Privater VIP Transfer",
    blogIstCityPrivateP1: "Der komfortabelste Weg ins Stadtzentrum. Ihr Fahrer erwartet Sie mit Namensschild und bringt Sie direkt zu Ihrem Hotel.",
    blogIstCityPrivateP2: "Festpreise, keine Überraschungen, keine Wartezeit - ideal für Familien, Gruppen oder wenn Sie nach einem langen Flug entspannt ankommen möchten.",
    blogIstCityTaxiTitle: "Reguläres Taxi",
    blogIstCityTaxiP1: "Taxis sind vor den Terminals verfügbar. Die Preise basieren auf dem Taxameter und können je nach Verkehr stark variieren.",
    blogIstCityTaxiP2: "Achten Sie auf offizielle gelbe Taxis und bestehen Sie auf das Taxameter. Trinkgeld ist üblich, aber nicht obligatorisch.",
    blogIstCityMetroTitle: "Metro (M11)",
    blogIstCityMetroP1: "Die Metro-Linie M11 verbindet den Istanbul Airport mit dem Stadtzentrum. Günstig und schnell, aber nicht ideal mit viel Gepäck.",
    blogIstCityMetroP2: "Vom Airport nach Gayrettepe/Mecidiyeköy dauert es etwa 30-40 Minuten. Von dort müssen Sie umsteigen, um Taksim oder Sultanahmet zu erreichen.",
    blogIstCityHavistTitle: "Havaist Bus",
    blogIstCityHavistP1: "Havaist-Busse fahren verschiedene Punkte in Istanbul an. Günstig und bequem, aber feste Routen und Zeiten.",
    blogIstCityHavistP2: "Haltestellen sind unter anderem Taksim, Kadıköy, Yenikapı und Beşiktaş. Die Fahrt nach Taksim dauert etwa 60-90 Minuten.",
    blogIstCityDistancesTitle: "Entfernungen und Fahrzeiten",
    blogIstCityToTaksim: "IST → Taksim: 45 km, 45-90 Min.",
    blogIstCityToSultanahmet: "IST → Sultanahmet: 50 km, 50-100 Min.",
    blogIstCityToKadikoy: "SAW → Kadıköy: 25 km, 30-60 Min.",
    blogIstCityTipsTitle: "Tipps für einen reibungslosen Transfer",
    blogIstCityTip1: "Buchen Sie Ihren Transfer im Voraus, besonders für Nachtankünfte",
    blogIstCityTip2: "Teilen Sie Ihre Flugnummer mit - wir überwachen Ihren Flug",
    blogIstCityTip3: "Haben Sie die Adresse Ihres Hotels bereit",
    blogIstCityTip4: "Vermeiden Sie Stoßzeiten (7-10 Uhr, 17-20 Uhr) wenn möglich",
    blogIstCityConclusionP1: "Für die meisten Reisenden ist der private Transfer die beste Option - Komfort, Festpreis und Tür-zu-Tür-Service machen den Unterschied nach einem langen Flug.",
    
    // Blog Island Intro and Popular Sections (Cyprus)
    blogCyprusIslandIntro: "Zypern ist eines der beliebtesten Reiseziele im Mittelmeer.",
    blogCyprusWhyPopular: "Warum Zypern so beliebt ist",
