    // Cappadocia Blog Translations - French
    blogCappadociaFaq1Q: "Quel aéroport est le plus proche de la Cappadoce ?",
    blogCappadociaFaq1A: "L'aéroport de Nevşehir-Cappadoce (NAV) n'est qu'à 40 km de Göreme. L'aéroport de Kayseri (ASR) est à 80 km mais offre plus d'options de vols.",
    blogCappadociaFaq2Q: "Combien de temps dure le transfert de l'aéroport à l'hôtel ?",
    blogCappadociaFaq2A: "De l'aéroport de Nevşehir à Göreme, il faut environ 35-45 minutes, de l'aéroport de Kayseri, il faut 60-75 minutes.",
    blogCappadociaFaq3Q: "Y a-t-il un service de transfert pour les tours en montgolfière ?",
    blogCappadociaFaq3A: "Oui, nous offrons un service de transfert tôt le matin pour les tours en montgolfière entre 04h00 et 05h00. La prise en charge à l'hôtel est incluse.",
    blogCappadociaFaq4Q: "Qu'est-ce qui est inclus dans les prix de transfert ?",
    blogCappadociaFaq4A: "Toutes les taxes, le suivi des vols, le temps d'attente gratuit (60 min), le service porte-à-porte, le siège enfant (sur demande) et l'assistance 24/7 sont inclus.",
