    blogCappadociaH1: "Guide Transfert Aéroport Cappadoce 2025 : Prix, Montgolfières & Hôtels",
    blogCappadociaIntro: "Service de transfert VIP des aéroports de Kayseri (ASR) et Nevşehir-Cappadoce (NAV) vers Göreme, Ürgüp et toutes les régions de Cappadoce. Prix actuels, transferts pour les tours en montgolfière et informations sur les hôtels populaires.",
    blogCappadociaHeroAlt: "Transfert Aéroport Cappadoce 2025 - Transfert VIP vers Hôtels Göreme, Ürgüp, Uçhisar",
    blogCappadociaTocHowToGet: "Comment se rendre en Cappadoce ?",
