    blogCappadociaHowToGetP2: "L'aéroport de Nevşehir est plus proche de Göreme (40 km), mais l'aéroport de Kayseri offre plus d'options de vols. Des vols réguliers opèrent depuis Istanbul, Ankara et d'autres grandes villes. La réservation anticipée est importante, surtout pendant les mois d'été et la saison des montgolfières d'avril à novembre, car les vols se remplissent rapidement.",
