    blogDubaiCtaButton: "Dubai Transferlerini Görüntüle",
    blogDubaiFaq1Q: "Dubai Havalimanı'ndan Downtown'a ne kadar sürer?",
    blogDubaiFaq1A: "Dubai Havalimanı'ndan Downtown Dubai'ye özel transfer, trafiğe bağlı olarak yaklaşık 15-25 dakika sürer.",
