    blogDubaiFaq6A: "Evet, Dubai Havalimanı'ndan Abu Dhabi'ye özel transferler sunuyoruz. Yolculuk yaklaşık 1 saat 15 dakika sürer.",

    // Dubai Blog - Additional Hardcoded Content (TR)
    blogDubaiMostVisited: "Dubai, yılda 16 milyondan fazla uluslararası turisti ağırlayan dünyanın en çok ziyaret edilen şehirlerinden biridir. Ultra modern mimarisi, lüks alışverişi ve canlı gece hayatıyla tanınan Dubai, benzersiz bir deneyim sunar. Havalimanı transferinizi planlamak, sorunsuz ve unutulmaz bir ziyaretin ilk adımıdır.",
    blogDubaiWhatToExpect: "Dubai'ye Varışta Sizi Neler Bekliyor",
    blogDubaiWhatToExpectP1: "Dubai Uluslararası Havalimanı (DXB), sürekli olarak dünyanın en yoğun havalimanları arasında yer almaktadır. Varışta, verimlilik göz önünde bulundurularak tasarlanmış etkileyici terminallerden geçeceksiniz. Göç işlemleri genellikle hızlıdır.",
    blogDubaiDXBDetails: "Şehir merkezinden sadece 4,6 km uzaklıkta bulunan DXB, Dubai'ye hizmet veren ana havalimanıdır. Üç terminali vardır: Terminal 1 çoğu uluslararası havayolunu, Terminal 2 düşük maliyetli taşıyıcıları ve Terminal 3 yalnızca Emirates yolcularını ağırlar.",
    blogDubaiDWCDetails: "Dubai'nin 37 km güneybatısında bulunan Al Maktoum Havalimanı, ağırlıklı olarak kargo ve bazı yolcu uçuşları için ikincil bir merkez olarak hizmet vermektedir.",
    blogDubaiPricingTitle: "Dubai Transfer Fiyatlandırmasını Anlama",
    blogDubaiPricingP1: "Dubai'nin transfer fiyatları mesafe, trafik koşulları ve seçtiğiniz hizmet türünden etkilenir. Ana arter olan Sheikh Zayed Road, yoğun saatlerde (7-9 ve 17-20) önemli trafik yaşayabilir. Sabit fiyatlandırmamız, trafik koşullarından bağımsız olarak ne ödeyeceğinizi bilmenizi sağlar.",
    blogDubaiLuxuryTitle: "Dubai Lüks Deneyimi",
    blogDubaiLuxuryP1: "Dubai lüks ile eş anlamlıdır ve havalimanı transferiniz bu standarda uygun olmalıdır. Premium filomuz en son Mercedes modellerini içerir ve varış noktanıza şık bir şekilde ulaşmanızı sağlar.",
    blogDubaiBookingTitle: "Önceden Rezervasyon mu, Varışta mı?",
    blogDubaiBookingP1: "Dubai Havalimanı'nda ulaşım seçenekleri mevcut olsa da, önceden rezervasyon önemli avantajlar sunar. Önceden rezerve edilmiş transferler, varış kapısından çıktığınızda şoförünüzün sizi beklediği anlamına gelir.",
    blogDubaiTipsTitle: "Temel Dubai Varış İpuçları",
    blogDubaiTip1: "Bağlı kalın:",
    blogDubaiTip1Desc: "Havalimanı genelinde ücretsiz WiFi mevcuttur",
    blogDubaiTip2: "Döviz bozdurma:",
    blogDubaiTip2Desc: "ATM'ler döviz bürolarından daha iyi kurlar sunar",
    blogDubaiTip3: "Kıyafet kuralı:",
    blogDubaiTip3Desc: "Dubai liberal olsa da, mütevazı giyim saygılıdır",
