    blogDubaiTip4Desc: "Konaklama sırasında toplu taşıma kullanacaksanız Nol kartı alın",
    blogDubaiTip5: "Yaz sıcağı:",
    blogDubaiTip5Desc: "Mayıs-Eylül arası sıcaklıklar 40°C'yi aşar - klimalı transfer şarttır",
    blogDubaiBeyondTitle: "Ünlü Simgelerin Ötesinde",
    blogDubaiBeyondP1: "Burj Khalifa ve Palm Jumeirah manşetleri kapsa da Dubai çok daha fazlasını sunar. Eski Dubai'ye bir bakış için tarihi Al Fahidi mahallesini keşfedin.",
    blogDubaiFinalP1: "Dubai, geldiğiniz andan itibaren etkileyen bir şehirdir. Birinci sınıf altyapısı, çarpıcı mimarisi ve sonsuz eğlence seçenekleriyle ziyaretiniz unutulmaz olacağa söz veriyor.",
    
